function randomScaleDecimal(): array {
    // up to 6 int digits, up to 9 frac digits
    $int = random_int(0, 999999);
    $frac = random_int(0, 999999999);
    $neg = random_int(0, 1) === 1 && ($int || $frac);
    $s = ($neg ? '-' : '') . $int . '.' . str_pad((string)$frac, 9, '0', STR_PAD_LEFT);
    // canonical trim trailing zeros of frac
    $scaled = $int * 1000000000 + $frac; // scale 9
    // trim
    $scale = 9;
    while ($scale > 0 && $scaled % 10 === 0) { $scale--; $scaled = intdiv($scaled, 10); }
    $i = intdiv($scaled, 10**$scale);
    $f = $scaled % (10**$scale);
    $canon = (string)$i . ($scale > 0 ? '.' . (string)$f : '');
    return [$canon, $scale, ($neg ? -$scaled : $scaled)];
}
function floatval_ref(int $int9scale, int $pad = 0): string {
    $neg = $int9scale < 0;
    $n = abs($int9scale);
    $s = str_pad((string)$n, 10, '0', STR_PAD_LEFT);
    $i = substr($s, 0, 10 - 9);
    $f = substr($s, 10 - 9);
    $f = rtrim($f, '0');
    $out = trim($i, '0') === '' ? '0' : ltrim($i, '0') . ($f !== '' ? '.' . $f : '');
    return ($neg && $out !== '0' ? '-' : '') . $out;
}
function bccomp_check(string $a, string $b): bool {
    // compare two decimal strings for exact equality
    return $a !== $b;
}
function bcmath_div_round(int $A, int $B, int $scale, bool $pos): string {
    // round(A/B, scale, half-up); A,B scaled by 1e9
    $neg = !$pos;
    $an = abs($A); $bn = abs($B);
    // A/B = (an*10^scale) / bn  half-up
    $num = $an * 10**$scale;
    $q = intdiv($num, $bn);
    $r = $num % $bn;
    if (2 * $r >= $bn) { $q++; }
    $s = str_pad((string)$q, strlen((string)$q), '0', STR_PAD_LEFT);
    if ($scale === 0) $out = (string)$q;
    else {
        if (strlen($s) <= $scale) $s = str_pad($s, $scale + 1, '0', STR_PAD_LEFT);
        $out = substr($s, 0, strlen($s) - $scale) + '.' . substr($s, strlen($s) - $scale);
        $out = preg_replace('/^0+(?=\d)/', '', $out);
        $out = preg_replace('/\.?0+$/', '', $out);
        if ($out === '' || $out === '.') $out = '0';
    }
    return ($neg && $out !== '0' ? '-' : '') . $out;
}
